encounters.patch_vs_task:
--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -1,4 +1,3 @@
-
 module TopModule(
    input   clk,
    input   rst_n,
@@ -9,35 +8,43 @@
 reg  [3:0] bin_out;
 wire [3:0] gray_wire;

-always @(posedge clk or negedge rst_n)begin
+reg toggle;
+
+always @(posedge clk or negedge rst_n) begin
    if(rst_n == 1'b0) begin
       bin_out <= 4'b0;
+      toggle <= 1'b0;
    end
    else begin
-      bin_out[3] = gray_wire[3];
-      bin_out[2] = gray_wire[2]&bin_out[3];
-      bin_out[1] = gray_wire[1]^bin_out[2];
-      bin_out[0] = gray_wire[0]^bin_out[1];
-   end 
+      if (toggle) begin
+         bin_out[3] <= gray_wire[3];
+         bin_out[2] <= gray_wire[2] ^ gray_wire[3];
+         bin_out[1] <= gray_wire[1] ^ gray_wire[2] ^ gray_wire[3];
+         bin_out[0] <= gray_wire[0] ^ gray_wire[1] ^ gray_wire[2] ^ gray_wire[3];
+      end
+      toggle <= ~toggle;
+   end
 end
+
 //Binary increment
 reg [3:0] bin_add_wire;
-always @(posedge clk or negedge rst_n)begin
+always @(posedge clk or negedge rst_n) begin
    if(rst_n == 1'b0) begin
       bin_add_wire <= 4'b0;
    end
-   else begin
+   else if (toggle) begin
       bin_add_wire <= bin_out + 1'b1;
    end
 end
+
 //Binary to gray code conversion
 assign gray_wire = (bin_add_wire >> 1) ^ bin_add_wire;

-always @(posedge clk or negedge rst_n)begin
+always @(posedge clk or negedge rst_n) begin
    if(rst_n == 1'b0) begin
       gray_out <= 4'b0;
    end
-   else begin
+   else if (toggle) begin
       gray_out <= gray_wire;
    end
 end
